CREATE OR REPLACE FUNCTION "public"."admin_dashboard_stats"("p_days" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_tz constant text := 'Asia/Shanghai';
  v_today timestamptz;
  v_start timestamptz;
  v_result jsonb;
begin
  if p_days is null or p_days < 7 or p_days > 90 then
    raise exception 'INVALID_INPUT' using detail = 'p_days must be between 7 and 90';
  end if;

  v_today := date_trunc('day', now() at time zone v_tz) at time zone v_tz;
  v_start := v_today - make_interval(days => p_days - 1);

  with windows(key, since) as (
    values ('today', v_today), ('7d', v_today - interval '6 days'), ('period', v_start)
  ),
  jobs as (
    select g.created_at,
           g.status,
           -- generation_jobs.provider is '<source>/<model>'; older rows hold a bare name.
           case when position('/' in g.provider) > 0
                then substr(g.provider, position('/' in g.provider) + 1)
                else coalesce(g.provider, 'unknown') end as model,
           coalesce(g.inputs ->> 'resolution', '1k') as resolution
      from public.generation_jobs g
     where g.created_at >= v_start
  ),
  -- Net credits spent on generation: reserves minus refunds, per pool.
  spend as (
    select l.created_at, l.pool, -l.delta as used
      from public.credit_ledger l
     where l.created_at >= v_start and l.kind in ('reserve', 'refund')
  ),
  -- A paying user is new on the day of their first purchase ever.
  first_purchases as (
    select l.user_id, min(l.created_at) as first_at
      from public.credit_ledger l
     where l.created_at >= v_start
       and l.kind = 'purchase'
       and not exists (
         select 1 from public.credit_ledger e
          where e.user_id = l.user_id and e.kind = 'purchase' and e.created_at < v_start
       )
     group by l.user_id
  ),
  window_stats as (
    select jsonb_agg(jsonb_build_object(
             'key', w.key,
             'since', w.since,
             'signups', (select count(*) from public.profiles p where p.created_at >= w.since),
             'jobs', (select count(*) from jobs j where j.created_at >= w.since),
             'succeeded', (select count(*) from jobs j where j.created_at >= w.since and j.status = 'succeeded'),
             'failed', (select count(*) from jobs j where j.created_at >= w.since and j.status = 'failed'),
             'free_credits_used', (select coalesce(sum(s.used), 0) from spend s where s.created_at >= w.since and s.pool = 'free'),
             'paid_credits_used', (select coalesce(sum(s.used), 0) from spend s where s.created_at >= w.since and s.pool = 'paid'),
             'new_paying_users', (select count(*) from first_purchases f where f.first_at >= w.since)
           ) order by w.since desc) as value
      from windows w
  ),
  trend as (
    select jsonb_agg(jsonb_build_object(
             'day', to_char(d.day at time zone v_tz, 'YYYY-MM-DD'),
             'jobs', (select count(*) from jobs j where j.created_at >= d.day and j.created_at < d.day + interval '1 day'),
             'succeeded', (select count(*) from jobs j
                            where j.created_at >= d.day and j.created_at < d.day + interval '1 day' and j.status = 'succeeded')
           ) order by d.day) as value
      from generate_series(v_start, v_today, interval '1 day') as d(day)
  ),
  by_model as (
    select jsonb_agg(jsonb_build_object(
             'model', m.model, 'resolution', m.resolution, 'jobs', m.jobs, 'succeeded', m.succeeded
           ) order by m.jobs desc, m.model, m.resolution) as value
      from (
        select j.model, j.resolution, count(*) as jobs, count(*) filter (where j.status = 'succeeded') as succeeded
          from jobs j
         group by j.model, j.resolution
      ) m
  )
  select jsonb_build_object(
           'timezone', v_tz,
           'days', p_days,
           'generated_at', now(),
           'windows', (select value from window_stats),
           'trend', coalesce((select value from trend), '[]'::jsonb),
           'by_model', coalesce((select value from by_model), '[]'::jsonb)
         )
    into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."admin_dashboard_stats"("p_days" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."support_tickets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "type" "text" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "payment_id" bigint,
    "job_id" "uuid",
    "refund_decision" "text",
    "refund_amount_cents" integer,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_message_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "user_seen_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "closed_at" timestamp with time zone,
    CONSTRAINT "support_tickets_closed" CHECK ((("status" = 'closed'::"text") = ("closed_at" IS NOT NULL))),
    CONSTRAINT "support_tickets_decision_amount" CHECK ((("refund_decision" = 'approved'::"text") = ("refund_amount_cents" IS NOT NULL))),
    CONSTRAINT "support_tickets_decision_type" CHECK ((("refund_decision" IS NULL) OR ("type" = 'refund'::"text"))),
    CONSTRAINT "support_tickets_job_type" CHECK ((("job_id" IS NULL) OR ("type" = 'image_issue'::"text"))),
    CONSTRAINT "support_tickets_payment_type" CHECK ((("payment_id" IS NULL) OR ("type" = ANY (ARRAY['billing'::"text", 'refund'::"text"])))),
    CONSTRAINT "support_tickets_refund_amount_cents_check" CHECK (("refund_amount_cents" > 0)),
    CONSTRAINT "support_tickets_refund_decision_check" CHECK (("refund_decision" = ANY (ARRAY['approved'::"text", 'rejected'::"text"]))),
    CONSTRAINT "support_tickets_refund_payment" CHECK ((("type" <> 'refund'::"text") OR ("payment_id" IS NOT NULL))),
    CONSTRAINT "support_tickets_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'replied'::"text", 'closed'::"text"]))),
    CONSTRAINT "support_tickets_type_check" CHECK (("type" = ANY (ARRAY['feedback'::"text", 'image_issue'::"text", 'billing'::"text", 'refund'::"text", 'account'::"text", 'other'::"text"])))
);


ALTER TABLE "public"."support_tickets" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_decide_refund"("p_ticket_id" "uuid", "p_decision" "text", "p_amount_cents" integer, "p_body" "text") RETURNS "public"."support_tickets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ticket public.support_tickets;
  v_left integer;
  v_body text := btrim(coalesce(p_body, ''));
begin
  if p_decision is null or p_decision not in ('approved', 'rejected') then
    raise exception 'INVALID_INPUT' using detail = 'decision must be approved or rejected';
  end if;
  if char_length(v_body) not between 1 and 2000 then
    raise exception 'INVALID_INPUT' using detail = 'a decision needs a reply of 1 to 2000 characters';
  end if;

  select * into v_ticket from public.support_tickets t where t.id = p_ticket_id for update;
  if not found then
    raise exception 'TICKET_NOT_FOUND';
  end if;
  if v_ticket.type <> 'refund' then
    raise exception 'INVALID_INPUT' using detail = 'not a refund ticket';
  end if;

  select p.amount_total - p.amount_refunded into v_left from public.payments p where p.id = v_ticket.payment_id;
  if p_decision = 'approved' and (p_amount_cents is null or p_amount_cents not between 1 and v_left) then
    raise exception 'INVALID_INPUT' using detail = 'amount must be between 1 and the unrefunded total';
  end if;
  if p_decision = 'rejected' and p_amount_cents is not null then
    raise exception 'INVALID_INPUT' using detail = 'a rejection takes no amount';
  end if;

  update public.support_tickets
     set refund_decision = p_decision,
         refund_amount_cents = p_amount_cents,
         status = 'replied',
         closed_at = null,
         last_message_at = now()
   where id = p_ticket_id
  returning * into v_ticket;

  insert into public.support_ticket_messages (ticket_id, author, body) values (p_ticket_id, 'admin', v_body);

  insert into public.admin_audit_log (action, user_id, target_id, reason)
  values (
    'decide_refund',
    v_ticket.user_id,
    p_ticket_id::text,
    format('退款工单：%s%s', p_decision, case when p_amount_cents is null then '' else ' ' || p_amount_cents end)
  );
  return v_ticket;
end;
$$;


ALTER FUNCTION "public"."admin_decide_refund"("p_ticket_id" "uuid", "p_decision" "text", "p_amount_cents" integer, "p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_template_requests"() RETURNS TABLE("id" "uuid", "email" "text", "description" "text", "image_keys" "text"[], "status" "text", "template_id" "text", "votes_count" integer, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select r.id, u.email::text, r.description, r.image_keys, r.status, r.template_id, r.votes_count, r.created_at
    from unnest(array['pending', 'live', 'shipped', 'rejected']) as s(status)
   cross join lateral (
           select t.id, t.user_id, t.description, t.image_keys, t.status, t.template_id, t.votes_count, t.created_at
             from public.template_requests t
            where t.status = s.status
            order by t.created_at desc
            limit 500
         ) r
    left join auth.users u on u.id = r.user_id
   order by r.created_at desc;
$$;


ALTER FUNCTION "public"."admin_list_template_requests"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_tickets"("p_status" "text", "p_type" "text", "p_cursor_at" timestamp with time zone, "p_cursor_id" "uuid", "p_limit" integer) RETURNS TABLE("id" "uuid", "user_id" "uuid", "email" "text", "type" "text", "status" "text", "payment_id" bigint, "job_id" "uuid", "refund_decision" "text", "created_at" timestamp with time zone, "last_message_at" timestamp with time zone, "preview" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_status is not null and p_status not in ('open', 'replied', 'closed') then
    raise exception 'INVALID_INPUT' using detail = 'unknown status';
  end if;
  if p_type is not null and p_type not in ('feedback', 'image_issue', 'billing', 'refund', 'account', 'other') then
    raise exception 'INVALID_INPUT' using detail = 'unknown ticket type';
  end if;
  if p_limit is null or p_limit not between 1 and 101 then
    raise exception 'INVALID_INPUT' using detail = 'p_limit must be between 1 and 101';
  end if;

  if p_status = 'open' then
    return query
      select t.id, t.user_id, u.email::text, t.type, t.status, t.payment_id, t.job_id, t.refund_decision,
             t.created_at, t.last_message_at, f.preview
        from public.support_tickets t
        left join auth.users u on u.id = t.user_id
        left join lateral (
          select left(m.body, 140) as preview from public.support_ticket_messages m
           where m.ticket_id = t.id order by m.created_at limit 1
        ) f on true
       where t.status = 'open'
         and (p_type is null or t.type = p_type)
         and (p_cursor_at is null or (t.last_message_at, t.id) < (p_cursor_at, p_cursor_id))
       order by t.last_message_at desc, t.id desc
       limit p_limit;
  else
    return query
      select t.id, t.user_id, u.email::text, t.type, t.status, t.payment_id, t.job_id, t.refund_decision,
             t.created_at, t.last_message_at, f.preview
        from public.support_tickets t
        left join auth.users u on u.id = t.user_id
        left join lateral (
          select left(m.body, 140) as preview from public.support_ticket_messages m
           where m.ticket_id = t.id order by m.created_at limit 1
        ) f on true
       where (p_status is null or t.status = p_status)
         and (p_type is null or t.type = p_type)
         and (p_cursor_at is null or (t.last_message_at, t.id) < (p_cursor_at, p_cursor_id))
       order by t.last_message_at desc, t.id desc
       limit p_limit;
  end if;
end;
$$;


ALTER FUNCTION "public"."admin_list_tickets"("p_status" "text", "p_type" "text", "p_cursor_at" timestamp with time zone, "p_cursor_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_reorder_templates"("p_ids" "text"[]) RETURNS "void"
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
  update public.templates t
  set sort_order = o.position * 10
  from unnest(p_ids) with ordinality as o(id, position)
  where t.id = o.id;
$$;


ALTER FUNCTION "public"."admin_reorder_templates"("p_ids" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_reply_ticket"("p_ticket_id" "uuid", "p_body" "text", "p_close" boolean) RETURNS "public"."support_tickets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_body text := nullif(btrim(coalesce(p_body, '')), '');
  v_ticket public.support_tickets;
begin
  if v_body is null and not coalesce(p_close, false) then
    raise exception 'INVALID_INPUT' using detail = 'a reply needs a message';
  end if;
  if char_length(v_body) > 2000 then
    raise exception 'INVALID_INPUT' using detail = 'body must be at most 2000 characters';
  end if;

  update public.support_tickets
     set status = case when p_close then 'closed' else 'replied' end,
         closed_at = case when p_close then coalesce(closed_at, now()) end,
         last_message_at = case when v_body is null then last_message_at else now() end
   where id = p_ticket_id
  returning * into v_ticket;
  if not found then
    raise exception 'TICKET_NOT_FOUND';
  end if;

  if v_body is not null then
    insert into public.support_ticket_messages (ticket_id, author, body) values (p_ticket_id, 'admin', v_body);
  end if;
  return v_ticket;
end;
$$;


ALTER FUNCTION "public"."admin_reply_ticket"("p_ticket_id" "uuid", "p_body" "text", "p_close" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_revenue_stats"("p_days" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_tz constant text := 'Asia/Shanghai';
  v_today timestamptz;
  v_start timestamptz;
  v_result jsonb;
begin
  if p_days is null or p_days < 7 or p_days > 90 then
    raise exception 'INVALID_INPUT' using detail = 'p_days must be between 7 and 90';
  end if;

  v_today := date_trunc('day', now() at time zone v_tz) at time zone v_tz;
  v_start := v_today - make_interval(days => p_days - 1);

  with windows(key, since) as (
    values ('today', v_today), ('7d', v_today - interval '6 days'), ('period', v_start)
  ),
  purchases as (
    select pm.created_at,
           pm.product_id,
           pm.channel,
           case when pm.currency = 'usd'
                then (pm.amount_total - pm.amount_tax - pm.amount_refunded) / 100.0
                else 0 end as amount
      from public.payments pm
     where pm.created_at >= v_start
  )
  select jsonb_build_object(
           'timezone', v_tz,
           'days', p_days,
           'generated_at', now(),
           'windows', (
             select jsonb_agg(jsonb_build_object(
                      'key', w.key,
                      'since', w.since,
                      'purchases', (select count(*) from purchases x where x.created_at >= w.since),
                      'revenue_usd', (select coalesce(sum(x.amount), 0) from purchases x where x.created_at >= w.since)
                    ) order by w.since desc)
               from windows w
           ),
           'by_product', coalesce((
             select jsonb_agg(jsonb_build_object(
                      'product_id', g.product_id, 'channel', g.channel,
                      'purchases', g.purchases, 'revenue_usd', g.revenue
                    ) order by g.revenue desc, g.product_id, g.channel)
               from (
                 select coalesce(x.product_id, 'unknown') as product_id, x.channel,
                        count(*) as purchases, sum(x.amount) as revenue
                   from purchases x
                  group by 1, 2
               ) g
           ), '[]'::jsonb),
           'trend', (
             select jsonb_agg(jsonb_build_object(
                      'day', to_char(d.day at time zone v_tz, 'YYYY-MM-DD'),
                      'revenue_usd', (select coalesce(sum(x.amount), 0) from purchases x
                                       where x.created_at >= d.day and x.created_at < d.day + interval '1 day')
                    ) order by d.day)
               from generate_series(v_start, v_today, interval '1 day') as d(day)
           ),
           'subscriptions', coalesce((
             select jsonb_object_agg(s.status, s.n)
               from (select status, count(*) as n from public.subscriptions group by status) s
           ), '{}'::jsonb)
         )
    into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."admin_revenue_stats"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_review_template_request"("p_request_id" "uuid", "p_status" "text", "p_template_id" "text" DEFAULT NULL::"text") RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current text;
  v_keys text[];
begin
  select r.status, r.image_keys into v_current, v_keys
    from public.template_requests r
   where r.id = p_request_id
     for update;
  if not found then
    raise exception 'REQUEST_NOT_FOUND';
  end if;

  if not (
       (v_current = 'pending' and p_status in ('live', 'rejected'))
    or (v_current = 'live' and p_status in ('rejected', 'shipped'))
  ) then
    raise exception 'REQUEST_TRANSITION_INVALID'
      using detail = v_current || ' -> ' || coalesce(p_status, 'null');
  end if;

  if p_status = 'shipped' then
    perform 1 from public.templates t where t.id = p_template_id;
    if not found then
      raise exception 'TEMPLATE_NOT_FOUND';
    end if;
  end if;

  update public.template_requests
     set status = p_status,
         template_id = case when p_status = 'shipped' then p_template_id end,
         image_keys = case when p_status = 'rejected' then '{}'::text[] else image_keys end,
         reviewed_at = now()
   where id = p_request_id;

  return case when p_status = 'rejected' then v_keys else '{}'::text[] end;
end;
$$;


ALTER FUNCTION "public"."admin_review_template_request"("p_request_id" "uuid", "p_status" "text", "p_template_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_search_users"("p_query" "text") RETURNS TABLE("id" "uuid", "email" "text", "created_at" timestamp with time zone, "provider" "text", "role" "text", "credits" integer, "free_credits" integer, "paid_until" timestamp with time zone, "generation_count" integer, "last_generation_at" timestamp with time zone, "banned_at" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select o.id, o.email, o.created_at, o.provider, o.role, o.credits, o.free_credits, o.paid_until,
         o.generation_count, o.last_generation_at, o.banned_at
    from admin.users_overview o
   -- The query is a literal substring: % and _ typed by the admin match themselves.
   where length(btrim(coalesce(p_query, ''))) > 0
     and o.email ilike '%' || replace(replace(replace(btrim(p_query), '\', '\\'), '%', '\%'), '_', '\_') || '%'
   order by o.created_at desc, o.id desc
   limit 50
$$;


ALTER FUNCTION "public"."admin_search_users"("p_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_provider_key"("p_id" "uuid", "p_key" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_secret uuid;
  v_name text := 'shotviva.provider.' || p_id::text;
begin
  -- Printable ASCII without whitespace, 16-1024 characters: every supported provider key fits.
  if p_key is not null and (char_length(p_key) not between 16 and 1024 or p_key !~ '^[!-~]+$') then
    raise exception 'PROVIDER_KEY_INVALID' using errcode = '23514';
  end if;

  select vault_secret_id into v_secret from public.ai_providers where id = p_id for update;
  if not found then
    raise exception 'PROVIDER_NOT_FOUND';
  end if;

  if p_key is null then
    delete from vault.secrets where id = v_secret or name = v_name;
    update public.ai_providers set vault_secret_id = null, api_key_last4 = null where id = p_id;
    return;
  end if;

  if v_secret is not null and exists (select 1 from vault.secrets where id = v_secret) then
    perform vault.update_secret(v_secret, p_key);
  else
    -- A leftover secret under this name is replaced, never reused blindly.
    delete from vault.secrets where name = v_name;
    v_secret := vault.create_secret(p_key, v_name, 'Shotviva image provider API key');
  end if;

  update public.ai_providers set vault_secret_id = v_secret, api_key_last4 = right(p_key, 4) where id = p_id;
end;
$_$;


ALTER FUNCTION "public"."admin_set_provider_key"("p_id" "uuid", "p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_unban_user"("p_user_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_reason is null or length(btrim(p_reason)) = 0 then
    raise exception 'INVALID_INPUT' using detail = 'reason is required';
  end if;

  update public.profiles set banned_at = null where id = p_user_id;
  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  insert into public.admin_audit_log (action, user_id, reason) values ('unban_user', p_user_id, p_reason);
end;
$$;


