CREATE OR REPLACE FUNCTION "public"."sync_subscription"("p_subscription_id" "text", "p_status" "text", "p_current_period_end" timestamp with time zone, "p_cancel_at_period_end" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_subscription_id is null or p_status is null or p_current_period_end is null or p_cancel_at_period_end is null then
    raise exception 'INVALID_INPUT' using detail = 'subscription fields are all required';
  end if;

  update public.subscriptions
     set status = p_status,
         current_period_end = p_current_period_end,
         cancel_at_period_end = p_cancel_at_period_end,
         updated_at = now()
   where stripe_subscription_id = p_subscription_id;
  return found;
end;
$$;


ALTER FUNCTION "public"."sync_subscription"("p_subscription_id" "text", "p_status" "text", "p_current_period_end" timestamp with time zone, "p_cancel_at_period_end" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."template_request_votes_count"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    update public.template_requests set votes_count = votes_count + new.weight where id = new.request_id;
  else
    update public.template_requests set votes_count = votes_count - old.weight where id = old.request_id;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."template_request_votes_count"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_template_request_vote"("p_request_id" "uuid", "p_user_id" "uuid") RETURNS TABLE("voted" boolean, "votes_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_status text;
  v_weight smallint;
begin
  if not public.wishlist_eligible(p_user_id) then
    raise exception 'WISHLIST_NOT_ELIGIBLE';
  end if;

  select r.status into v_status from public.template_requests r where r.id = p_request_id for update;
  if not found then
    raise exception 'REQUEST_NOT_FOUND';
  end if;
  if v_status <> 'live' then
    raise exception 'REQUEST_NOT_LIVE';
  end if;

  delete from public.template_request_votes v
   where v.request_id = p_request_id and v.user_id = p_user_id;
  if found then
    voted := false;
  else
    v_weight := case when public.current_tier(p_user_id) = 'max' then 3 else 1 end;
    insert into public.template_request_votes (request_id, user_id, weight)
    values (p_request_id, p_user_id, v_weight);
    voted := true;
  end if;

  select r.votes_count into votes_count from public.template_requests r where r.id = p_request_id;
  return next;
end;
$$;


ALTER FUNCTION "public"."toggle_template_request_vote"("p_request_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wishlist_eligible"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
           select 1 from public.generation_jobs j
            where j.user_id = p_user_id and j.status = 'succeeded'
         )
     and exists (
           select 1 from public.profiles p
            where p.id = p_user_id and p.banned_at is null
         );
$$;


ALTER FUNCTION "public"."wishlist_eligible"("p_user_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."profiles" (
    "id" "uuid" NOT NULL,
    "role" "text" DEFAULT 'user'::"text" NOT NULL,
    "credits" integer DEFAULT 0 NOT NULL,
    "paid_until" timestamp with time zone,
    "signup_ip" "inet",
    "banned_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "free_credits" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "profiles_credits_check" CHECK (("credits" >= 0)),
    CONSTRAINT "profiles_free_credits_check" CHECK (("free_credits" >= 0)),
    CONSTRAINT "profiles_role_check" CHECK (("role" = ANY (ARRAY['user'::"text", 'admin'::"text"])))
);


ALTER TABLE "public"."profiles" OWNER TO "postgres";


CREATE OR REPLACE VIEW "admin"."users_overview" AS
 SELECT "u"."id",
    ("u"."email")::"text" AS "email",
    "u"."created_at",
    COALESCE(( SELECT "string_agg"("provider"."value", ', '::"text" ORDER BY "provider"."value") AS "string_agg"
           FROM "jsonb_array_elements_text"(COALESCE(("u"."raw_app_meta_data" -> 'providers'::"text"), '[]'::"jsonb")) "provider"("value")), ("u"."raw_app_meta_data" ->> 'provider'::"text")) AS "provider",
    "p"."role",
    "p"."credits",
    "p"."free_credits",
    "p"."paid_until",
    COALESCE("j"."generation_count", 0) AS "generation_count",
    "j"."last_generation_at",
    "p"."banned_at"
   FROM (("auth"."users" "u"
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "u"."id")))
     LEFT JOIN LATERAL ( SELECT ("count"(*))::integer AS "generation_count",
            "max"("g"."created_at") AS "last_generation_at"
           FROM "public"."generation_jobs" "g"
          WHERE ("g"."user_id" = "u"."id")) "j" ON (true));


ALTER VIEW "admin"."users_overview" OWNER TO "postgres";


COMMENT ON VIEW "admin"."users_overview" IS 'Owner support view (ARCHITECTURE §10): search by email; credits = paid pool, free_credits = free pool.';



CREATE TABLE IF NOT EXISTS "public"."admin_audit_log" (
